/**
 * Link version 1, frozen: the bankroll, join, photo and currency-spend channels.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 1 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV1.test.ts` checks the living types against it.
 */

import type {
    ChosenAnnotationV1,
    ListedPhotoV1,
    OpenChallengeV1,
    PhotoStatsAnswerV1,
    SwapCandidateV1,
} from './shapesChallenges';

export type PhotosChannelsV1 = {
    'fill-exposure': {
        args: [challengeId: string | number, confirmed: boolean];
        result:
            | { success: false; error: string }
            | { success: false; outcome: undefined | string; error: undefined | string }
            | { success: true; outcome: 'ok' };
    };
    'forget-unconfirmed-payment': {
        args: [challengeId: string | number];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { status: 'not-authenticated'; success: false; error: string }
            | { success: true; status: 'forgotten'; error?: undefined }
            | {
                  success: false;
                  error: 'not-authenticated' | 'nothing-to-forget' | 'busy' | 'unreadable' | 'locks-unavailable';
                  status: 'not-authenticated' | 'nothing-to-forget' | 'busy' | 'unreadable' | 'locks-unavailable';
              };
    };
    'get-auto-claim-status': {
        args: [];
        result: { success: false; error: string } | { enabled: boolean; nextClaimAt: number; success: true };
    };
    'get-auto-join-active': {
        args: [];
        result: { success: true; active: boolean } | { success: false; active: boolean };
    };
    'get-bankroll': {
        args: [];
        result:
            | { success: false; error: string }
            | { success: true; keys: number; swaps: number; fills: number; coins: number };
    };
    'get-library-photos': {
        args: [
            challengeId?: undefined | null | string | number,
            search?: undefined | null | string,
            mode?: undefined | 'fresh' | 'cached',
            usage?: undefined | 'submit' | 'swap',
            start?: undefined | null | number,
            keep?: undefined | null | number,
            order?: undefined | 'votes' | 'newest' | 'oldest',
        ];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | {
                  preview: boolean;
                  photos: ListedPhotoV1[];
                  memberId: null | string;
                  wonIds: string[];
                  wonCount: number;
                  truncated: boolean;
                  nextStart: number;
                  allowedKnown: boolean;
                  readAtMs: number;
                  success: true;
              };
    };
    'get-member-challenges': {
        args: [];
        result:
            | { success: false; error: string }
            | { success: false; error: string; items: never[] }
            | { success: true; items: OpenChallengeV1[]; error?: undefined };
    };
    'get-open-chosen-annotations': {
        args: [ids: (string | number)[]];
        result:
            | { success: false; error: 'invalid-args' }
            | { success: true; annotations: { [key: string]: ChosenAnnotationV1 } }
            | { annotations: {}; success: false; error: string };
    };
    'get-photo-stats': {
        args: [ids?: unknown];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { success: true; stats: PhotoStatsAnswerV1[]; missing: string[] };
    };
    'get-swap-backs': {
        args: [challengeId: string | number];
        result:
            | { success: false; outcome: undefined | string; error: undefined | string }
            | {
                  success: true;
                  items: {
                      currentId: string;
                      previousId: string;
                      previousMemberId: string;
                      kind: 'boost' | 'turbo' | 'guruPick';
                  }[];
                  error?: undefined;
              }
            | { success: false; items: never[]; error: 'api-failed' };
    };
    'join-challenge': {
        args: [challengeId: string | number, spendCoins?: boolean | undefined, expectedCost?: undefined | number];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | {
                  success: boolean;
                  status: string;
                  cost: number;
                  coins: undefined | number;
                  challengeId: string | number;
                  reason: undefined | 'unconfirmed' | 'no-photo' | 'already-joined' | 'full' | 'price-unknown';
                  coinsBefore: undefined | number;
              };
    };
    'key-unlock-boost': {
        args: [challengeId: string | number, confirmed: boolean];
        result:
            | { success: false; error: string }
            | { success: false; outcome: undefined | string; error: undefined | string }
            | { success: true; outcome: 'ok' };
    };
    'preview-swap-photo': {
        args: [challengeId: string | number, imageId: string | number, chosenId?: undefined | null | string | number];
        result:
            | { success: false; error: string }
            | { success: false; outcome: undefined | string; error: undefined | string }
            | { success: true; outcome: 'ok'; candidate: SwapCandidateV1 };
    };
    'search-photo-tags': {
        args: [term?: undefined | string];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { success: true; tags: string[] };
    };
    'submit-picked-photos': {
        args: [challengeId: string | number, imageIds: string[]];
        result:
            | { success: false; error: string }
            | { success: false; error: 'invalid-args' }
            | { success: false; error: 'challenge-data-incomplete' }
            | { success: false; error: 'Challenge no longer active' }
            | { success: true; submitted: number };
    };
    'suggest-photos': {
        args: [challengeId: string | number, usage?: undefined | 'submit' | 'swap', exclude?: undefined | string[]];
        result:
            | { success: false; error: 'invalid-args' }
            | { success: false; error: 'challenge-data-incomplete' }
            | { success: false; error: 'Challenge no longer active' }
            | { success: false; error: string }
            | {
                  success: true;
                  memberId: null | string;
                  photos: {
                      id: string;
                      labels: string[];
                      allowed: boolean;
                      message: null | string;
                      uploadDate: null | number;
                  }[];
                  statsLimited: boolean;
              };
    };
    'swap-back-entry-photo': {
        args: [challengeId: string | number, currentImageId: string | number, confirmed: boolean];
        result:
            | { success: false; error: string }
            | { success: false; outcome: undefined | string; error: undefined | string }
            | { success: true; outcome: 'ok' };
    };
    'swap-entry-photo': {
        args: [challengeId: string | number, imageId: string | number, newImageId: string | number, confirmed: boolean];
        result:
            | { success: false; error: string }
            | { success: false; outcome: undefined | string; error: undefined | string }
            | { success: true; outcome: 'ok' };
    };
};
